diff --git a/internal/workspace/libs/loader_copies_test.go b/internal/workspace/libs/loader_copies_test.go
new file mode 100644
index 0000000000..71e46902f4
--- /dev/null
+++ b/internal/workspace/libs/loader_copies_test.go
@@ -0,0 +1,99 @@
+package libs
+
+import (
+	"os"
+	"path/filepath"
+	"sort"
+	"strings"
+	"testing"
+
+	"github.com/Open-MBEE/OpenSysML/internal/semantic/resolve"
+	"github.com/Open-MBEE/OpenSysML/internal/semantic/semantics"
+	"github.com/Open-MBEE/OpenSysML/internal/semantic/symbols"
+)
+
+// copiedLibrary writes two copies of a one-file library under dir; a parse of
+// either copy resolves D's supertype to the B declared beside it.
+func copiedLibrary(t *testing.T, dir string) {
+	t.Helper()
+	for _, copy := range []string{"one", "two"} {
+		path := filepath.Join(dir, copy, "Lib.kerml")
+		if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
+			t.Fatal(err)
+		}
+		if err := os.WriteFile(path, []byte("package Lib { class B; class D :> B; }"), 0o600); err != nil {
+			t.Fatal(err)
+		}
+	}
+}
+
+// supertypesByDocument is the document and name of every direct supertype of
+// every symbol idx holds, keyed by the symbol's own document and name.
+func supertypesByDocument(idx *symbols.Index) map[string]string {
+	model := semantics.NewModel(resolve.New(idx))
+	out := map[string]string{}
+	var walk func(doc string, s *symbols.Scope)
+	walk = func(doc string, s *symbols.Scope) {
+		for _, sym := range s.Members() {
+			var sups []string
+			for _, sup := range model.DirectSupertypes(sym) {
+				sups = append(sups, sup.DocName+"#"+symbols.FQNOf(sup))
+			}
+			sort.Strings(sups)
+			out[doc+"#"+symbols.FQNOf(sym)] = strings.Join(sups, " ")
+			if sym.Scope != nil {
+				walk(doc, sym.Scope)
+			}
+		}
+	}
+	for _, doc := range idx.Documents() {
+		walk(doc, idx.DocumentRoot(doc))
+	}
+	return out
+}
+
+// Two files of equal content are two documents, each resolving its references
+// from its own place in the library: the record of one copy must not be
+// restored for the other, or the warm load wires a copy's supertypes to the
+// other copy's declarations where the cold load resolved them within itself.
+func TestLoaderRestoresEachCopyFromItsOwnRecord(t *testing.T) {
+	dir := t.TempDir()
+	copiedLibrary(t, dir)
+	cache := &Cache{dir: t.TempDir()}
+	src := NewDirSource(dir)
+
+	cold := symbols.NewIndex()
+	if err := NewLoader(src, cache).LoadAll(cold); err != nil {
+		t.Fatalf("cold load: %v", err)
+	}
+	warmLoader := NewLoader(src, cache)
+	warm := symbols.NewIndex()
+	if err := warmLoader.LoadAll(warm); err != nil {
+		t.Fatalf("warm load: %v", err)
+	}
+	if got, want := warmLoader.Hits(), len(src.List()); got != want {
+		t.Fatalf("warm load restored %d documents, want all %d", got, want)
+	}
+
+	coldSupers, warmSupers := supertypesByDocument(cold), supertypesByDocument(warm)
+	for key, want := range coldSupers {
+		if got := warmSupers[key]; got != want {
+			t.Errorf("%s: warm supertypes %q, cold %q", key, got, want)
+		}
+	}
+	for _, copy := range []string{"one", "two"} {
+		key := copy + "/Lib.kerml#Lib::D"
+		if want := copy + "/Lib.kerml#Lib::B"; coldSupers[key] != want {
+			t.Errorf("%s: cold supertypes %q, want %q", key, coldSupers[key], want)
+		}
+	}
+}
+
+// A record names the documents its facts refer to, so equal content under two
+// names is two records.
+func TestCacheKeyDependsOnDocumentName(t *testing.T) {
+	c := &Cache{dir: t.TempDir()}
+	if c.keyFor("one/Base.kerml", []byte("alpha"), "set") == c.keyFor("two/Base.kerml", []byte("alpha"), "set") {
+		t.Fatal("equal content under two names produced one cache key")
+	}
+}
diff --git a/internal/workspace/model/library_copies_test.go b/internal/workspace/model/library_copies_test.go
new file mode 100644
index 0000000000..5af064c1a3
--- /dev/null
+++ b/internal/workspace/model/library_copies_test.go
@@ -0,0 +1,91 @@
+package model
+
+import (
+	"strings"
+	"testing"
+
+	"github.com/Open-MBEE/OpenSysML/internal/semantic/symbols"
+	"github.com/Open-MBEE/OpenSysML/internal/workspace/libs"
+)
+
+// copiedSource lists every file of a library source under each of the given
+// prefixes, the way a library path holding several copies of the library does.
+type copiedSource struct {
+	inner    libs.Source
+	prefixes []string
+}
+
+func (s copiedSource) List() []string {
+	var out []string
+	for _, prefix := range s.prefixes {
+		for _, name := range s.inner.List() {
+			out = append(out, prefix+"/"+name)
+		}
+	}
+	return out
+}
+
+func (s copiedSource) Read(name string) ([]byte, error) {
+	for _, prefix := range s.prefixes {
+		if rest, ok := strings.CutPrefix(name, prefix+"/"); ok {
+			return s.inner.Read(rest)
+		}
+	}
+	return s.inner.Read(name)
+}
+
+// connectionEndsModel inherits `self` into each connection end through Part
+// twice over, which two library copies wired into one another report as a
+// duplicate inherited name.
+const connectionEndsModel = `package Test {
+	part def C {
+		connection c {
+			end part p1;
+			end part p2;
+		}
+	}
+}`
+
+// A workspace reports the same diagnostics whether its library's facts were
+// derived from the parsed files or restored from the records the previous load
+// wrote, whatever number of copies of the library the source holds.
+func TestDiagnosticsAgreeAcrossColdAndWarmLibraryLoads(t *testing.T) {
+	for _, tc := range []struct {
+		name   string
+		copies []string
+	}{
+		{"one copy", []string{"lib"}},
+		{"two copies", []string{"one", "two"}},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			src := copiedSource{inner: libs.BundledSource(), prefixes: tc.copies}
+			cache, err := libs.NewCacheIn(t.TempDir())
+			if err != nil {
+				t.Fatalf("cache: %v", err)
+			}
+			var runs []string
+			for _, state := range []string{"cold", "warm"} {
+				base := symbols.NewIndex()
+				loader := libs.NewLoader(src, cache)
+				if err := loader.LoadAll(base); err != nil {
+					t.Fatalf("%s load: %v", state, err)
+				}
+				if state == "warm" && loader.Hits() != len(src.List()) {
+					t.Fatalf("warm load restored %d documents, want all %d", loader.Hits(), len(src.List()))
+				}
+				base.Freeze()
+				ws := NewWorkspaceWithIndex(symbols.NewOverlay(base), WithLibrarySource(src))
+				const uri = "file:///ws/connection.sysml"
+				ws.Open(uri, []byte(connectionEndsModel), 1)
+				runs = append(runs, strings.Join(diagnosticMessages(ws, uri), "\n"))
+				ws.Close(uri)
+			}
+			if runs[0] != runs[1] {
+				t.Errorf("diagnostics differ between the cold and the warm load:\ncold:\n%s\nwarm:\n%s", runs[0], runs[1])
+			}
+			if strings.Contains(runs[1], "Duplicate of inherited member name") {
+				t.Errorf("warm load reports a duplicate inherited name:\n%s", runs[1])
+			}
+		})
+	}
+}

