+  );
+  const content = childrenArray.filter(
+    (child) => !isElementOfType(child, SplitWithColumnStacks.HeaderConfig)
   );
+  return [...headerConfigs, <SafeAreaProvider key="content">{content}</SafeAreaProvider>];
