+/// `--output -` is stdout, not stdin.
+pub(crate) fn args_read_stdin(matched_args: &clap::ArgMatches) -> bool {
+    matched_args.ids().filter(|id| id.as_str() != "output").any(|id| {
+        matched_args
+            .get_raw(id.as_str())
+            .into_iter()
+            .flatten()
