+    let Some(field) = param_def.shorthand_field.as_deref() else {
+        return Vec::new();
+    };
+    raw.split(',')
+        .map(str::trim)
+        .filter(|part| !part.is_empty())
+        .map(|part| serde_json::json!({ field: part }))
+        .collect()
